sys_script.script:
(function executeRule(current, previous) {

    try {

        // =====================================================
        // REQUEST NUMBER
        // =====================================================
        var number =
            current.getValue('number') ||
            'Correction Request';


        // =====================================================
        // CREATED DATE/TIME -> IST
        // =====================================================
        var created =
            current.getValue('sys_created_on');

        var formattedCreated =
            '-';


        if (created) {

            var indiaDateTime =
                new GlideDateTime(created);

            // UTC + 05:30
            indiaDateTime.addSeconds(19800);


            var indiaValue =
                indiaDateTime.getValue();


            var datePart =
                indiaValue.substring(
                    0,
                    10
                );


            var timePart =
                indiaValue.substring(
                    11,
                    16
                );


            formattedCreated =
                formatDate(
                    datePart
                ) +
                ' ' +
                formatTime12Hour(
                    timePart
                );

        }


        // =====================================================
        // REQUESTED STATUS
        // =====================================================
        var requestedStatusRaw =
            current.getDisplayValue(
                'requested_status'
            ) ||
            current.getValue(
                'requested_status'
            ) ||
            '-';


        var requestedStatus =
            humanizeChoice(
                requestedStatusRaw
            );


        // =====================================================
        // REQUEST STATE
        // =====================================================
        var stateRaw =
            current.getDisplayValue(
                'state'
            ) ||
            current.getValue(
                'state'
            ) ||
            '-';


        var state =
            humanizeChoice(
                stateRaw
            );


        // =====================================================
        // FINAL REFERENCE LABEL
        // =====================================================
        var referenceLabel =
            number +
            ' • ' +
            formattedCreated +
            ' • ' +
            requestedStatus +
            ' • ' +
            state;


        current.setValue(
            'reference_label',
            referenceLabel
        );


        // =====================================================
        // DATE FORMAT
        // 2026-10-12 -> 12-Oct-2026
        // =====================================================
        function formatDate(value) {

            if (!value) {
                return '-';
            }


            var parts =
                String(value)
                    .split('-');


            if (
                parts.length !== 3
            ) {
                return value;
            }


            var months = [
                'Jan',
                'Feb',
                'Mar',
                'Apr',
                'May',
                'Jun',
                'Jul',
                'Aug',
                'Sep',
                'Oct',
                'Nov',
                'Dec'
            ];


            var monthIndex =
                parseInt(
                    parts[1],
                    10
                ) - 1;


            if (
                monthIndex < 0 ||
                monthIndex > 11
            ) {
                return value;
            }


            return (
                parts[2] +
                '-' +
                months[monthIndex] +
                '-' +
                parts[0]
            );

        }


        // =====================================================
        // TIME FORMAT
        // 16:53 -> 4:53 PM
        // =====================================================
        function formatTime12Hour(value) {

            if (!value) {
                return '-';
            }


            var parts =
                String(value)
                    .split(':');


            if (
                parts.length < 2
            ) {
                return value;
            }


            var hour =
                parseInt(
                    parts[0],
                    10
                );


            var minute =
                parts[1];


            var suffix =
                hour >= 12
                    ? 'PM'
                    : 'AM';


            hour =
                hour % 12;


            if (
                hour === 0
            ) {
                hour = 12;
            }


            return (
                hour +
                ':' +
                minute +
                ' ' +
                suffix
            );

        }


        // =====================================================
        // HUMANIZE CHOICE
        //
        // half_day           -> Half Day
        // insufficient_hours -> Insufficient Hours
        // pending_approval    -> Pending Approval
        // =====================================================
        function humanizeChoice(value) {

            if (
                !value ||
                value === '-'
            ) {
                return '-';
            }


            var text =
                String(value)
                    .replace(
                        /_/g,
                        ' '
                    )
                    .replace(
                        /-/g,
                        ' '
                    );


            var words =
                text.split(' ');


            for (
                var i = 0;
                i < words.length;
                i++
            ) {

                if (words[i]) {

                    words[i] =
                        words[i]
                            .charAt(0)
                            .toUpperCase() +
                        words[i]
                            .substring(1)
                            .toLowerCase();

                }

            }


            return words.join(' ');

        }


    }
    catch (e) {

        gs.error(
            '[SmartAttend Correction Reference] ' +
            e.message
        );

    }

})(current, previous);
